      "insight": "Show the complete deployment pipeline from dev through staging, canary, and production environments, making the sequential progression and branching decision points visually prominent"
    },
    {
      "id": "rollback-paths",
      "insight": "Highlight all automatic rollback paths that can trigger when health checks or error-rate thresholds fail, visually distinguishing them from the forward deployment flow"
    },
    {
      "id": "blue-green-switch-mechanism",
      "insight": "Emphasize the blue-green traffic switching logic at the production stage, showing how traffic shifts between active and standby slots and the decision gate that governs the cutover"
    },
    {
      "id": "hpa-scaling-decision-points",
      "insight": "Mark the HPA scaling decision checkpoints at each environment stage, showing the CPU/memory thresholds that trigger scale-up or scale-down actions"
    },
    {
      "id": "swimlane-environment-separation",
      "insight": "Use swimlane-style separation so that each environment (dev, staging, canary, production) occupies a distinct visual lane, making cross-environment transitions and parallel activities easy to trace"
    }
  ]
}

