cat << 'EOF' > generate_mmd.py
import json

with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)

nodes = data['pipeline_nodes']['data']
edges = data['pipeline_edges']['data']

# organize nodes by lane
lanes = {"dev": [], "staging": [], "canary": [], "production": [], "global": []}
for n in nodes:
    lanes[n['lane']].append(n)

# build mermaid
lines = []
lines.append("%%{init: {'theme': 'base', 'themeVariables': { 'primaryColor': '#0891b2', 'edgeLabelBackground':'#1e293b', 'tertiaryColor': '#1e293b'}}}%%")
lines.append("graph TD")

# add subgraphs for each lane
lane_order = ["dev", "staging", "canary", "production", "global"]
for lane in lane_order:
    lines.append(f"  subgraph {lane.upper()}")
    for n in lanes[lane]:
        node_id = n['id']
        label = n['label'].replace('"', "'")
        node_type = n['type']

        # Format label based on type
        extra = ""
        if node_type == "hpa_decision":
            extra = f"<br/>[CPU: {n['cpu_threshold_pct']}% | Mem: {n['mem_threshold_pct']}%]"
        elif node_type == "decision" and 'error_rate_threshold_pct' in n:
            err = n['error_rate_threshold_pct']
            p99 = n.get('p99_latency_ms_threshold')
            extra = f"<br/>[Err< {err}%]" + (f" [p99< {p99}ms]" if p99 else "")
        elif 'traffic_pct' in n:
            extra = f"<br/>[Traffic: {n['traffic_pct']}%]"
        elif 'duration_min' in n:
            extra = f"<br/>[{n['duration_min']} min]"

        full_label = f"{label}{extra}"

        # Shape based on type
        if node_type == 'action':
            lines.append(f"    {node_id}[\"{full_label}\"]")
        elif node_type in ('check', 'hpa_action', 'rollback'):
            lines.append(f"    {node_id}([\"{full_label}\"])")
        elif node_type in ('decision', 'hpa_decision'):
            lines.append(f"    {node_id}{{\"{full_label}\"}}")
        elif node_type == 'terminal':
            lines.append(f"    {node_id}((\"{full_label}\"))")
        else:
            lines.append(f"    {node_id}[\"{full_label}\"]")

        # Class styling
        if node_type == 'rollback':
            lines.append(f"    class {node_id} rollbackNode")
        elif node_type == 'hpa_decision':
            lines.append(f"    class {node_id} hpaNode")
        elif node_type == 'decision':
            lines.append(f"    class {node_id} decisionNode")

    lines.append("  end")

for e in edges:
    f = e['from']
    t = e['to']
    lbl = e.get('label', '')
    etype = e.get('type', '')

    edge_str = f"{f}"
    if etype == 'rollback':
        if lbl:
            edge_str += f" -. \"{lbl}\" .-> {t}"
        else:
            edge_str += f" -.-> {t}"
    elif etype == 'blue_green':
        if lbl:
            edge_str += f" ==>|\"{lbl}\"| {t}"
        else:
            edge_str += f" ==> {t}"
    else:
        if lbl:
            edge_str += f" -->|\"{lbl}\"| {t}"
        else:
            edge_str += f" --> {t}"

    lines.append("  " + edge_str)

# class definitions
lines.append("  classDef rollbackNode fill:#7f1d1d,stroke:#ef4444,color:#fca5a5,stroke-width:2px,stroke-dasharray: 5 5;")
lines.append("  classDef hpaNode fill:#14532d,stroke:#22c55e,color:#bbf7d0;")
lines.append("  classDef decisionNode fill:#4c1d95,stroke:#8b5cf6,color:#ddd6fe;")
lines.append("  classDef default fill:#0f172a,stroke:#38bdf8,color:#e0f2fe;")

with open('pipeline.mmd', 'w') as f:
    f.write('\n'.join(lines))
EOF
python3 generate_mmd.py
cat pipeline.mmd

